<?php get_header(); $type=get_post_type();$obj=get_post_type_object($type);$dest=isset($_GET['destination'])?sanitize_title(wp_unslash($_GET['destination'])):''; ?><section class="nv-content"><div class="nv-wrap"><div class="nv-eyebrow"><?php esc_html_e('Explore opportunities','nvconsult'); ?></div><h1><?php echo esc_html($obj?$obj->labels->name:__('Opportunities','nvconsult')); ?></h1><form class="nv-filter" method="get"><label><span><?php esc_html_e('Search','nvconsult'); ?></span><input type="search" name="s" value="<?php echo esc_attr(get_search_query()); ?>" placeholder="<?php esc_attr_e('Keyword, course, role…','nvconsult'); ?>"></label><?php $terms=get_terms(['taxonomy'=>'nv_destination','hide_empty'=>true]);if(!is_wp_error($terms)&&$terms): ?><label><span><?php esc_html_e('Destination','nvconsult'); ?></span><select name="destination"><option value=""><?php esc_html_e('All destinations','nvconsult'); ?></option><?php foreach($terms as$t): ?><option value="<?php echo esc_attr($t->slug); ?>" <?php selected($dest,$t->slug); ?>><?php echo esc_html($t->name); ?></option><?php endforeach; ?></select></label><?php endif; ?><button class="nv-btn" type="submit"><?php esc_html_e('Search','nvconsult'); ?></button></form><div class="nv-listing"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="nv-card"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large',['class'=>'nv-thumb']); ?><div class="nv-meta"><?php $ds=get_the_terms(get_the_ID(),'nv_destination');if($ds&&!is_wp_error($ds))echo esc_html(implode(' · ',wp_list_pluck($ds,'name'))); ?></div><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),24)); ?></p><a class="nv-link" href="<?php the_permalink(); ?>"><?php esc_html_e('View details →','nvconsult'); ?></a></article><?php endwhile;else:?><div class="nv-card"><h3><?php esc_html_e('No opportunities found','nvconsult'); ?></h3><p><?php esc_html_e('Try another keyword or destination.','nvconsult'); ?></p></div><?php endif; ?></div><?php the_posts_pagination(); ?></div></section><?php get_footer(); ?>
